"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6095],{46887:e=>{e.exports=JSON.parse('{"functions":[{"name":"getDescription","desc":"Gets the character description for a player instance or userId.\\n\\nThe appearance fetch is retried up to 4 times and falls back to a blank\\n`HumanoidDescription` if it never succeeds, so a Roblox API outage produces\\na default avatar rather than a failed spawn. Passing nil skips the fetch\\nentirely and returns the normalised default.\\n\\nWhatever the source, the result is normalised the same way: all body scales\\npinned (`BodyTypeScale` 0.3, the rest 1) so avatars cannot alter their\\neffective size, and the back and waist accessory slots cleared so\\ngame-applied accessories have those slots to themselves.","params":[{"name":"arg","desc":"player or userId whose appearance to load","lua_type":"Player | number?"}],"returns":[{"desc":"","lua_type":"HumanoidDescription"}],"function_type":"static","source":{"line":77,"path":"src/Server/Util/Character.luau"}},{"name":"createModel","desc":"Creates an R15 character model for a player from their normalised\\ndescription.\\n\\nBundled Roblox character scripts are destroyed except `Animate`, which is\\nkept so walk/run/idle animations work without a replacement system.\\n[Character.preSpawn] always runs before the model is exposed.\\n\\nWith `spawn` true the model is parented to the Workspace and assigned to\\n`player.Character` here, and [Character.onSpawn] fires immediately. With\\n`spawn` falsy the model is returned unparented and a one-shot listener fires\\n[Character.onSpawn] whenever the caller parents it \u2014 which is what\\n[PlayerService] relies on, since it positions and unanchors the character\\nitself.","params":[{"name":"player","desc":"character owner","lua_type":"Player"},{"name":"spawn","desc":"parent to the Workspace immediately","lua_type":"boolean?"}],"returns":[{"desc":"the character, or nil if the player left mid-build","lua_type":"Model?"}],"function_type":"static","source":{"line":139,"path":"src/Server/Util/Character.luau"}},{"name":"preSpawn","desc":"Called before a player\'s character model is placed in the workspace \u2014 the\\nhook for anything that must be true of a character before it is ever\\nvisible.\\n\\nStrips blacklisted instances (scripts, sounds and particle effects) out of\\nevery accessory handle, so an avatar cannot smuggle client scripts or noisy\\neffects into the game. Applies the player\'s equipped items, currently inert\\nwhile [ItemProcessor] is stubbed. Ragdoll rigging is set up on a separate\\nthread so it cannot block the spawn.","params":[{"name":"player","desc":"character owner","lua_type":"Player"},{"name":"character","desc":"the not-yet-parented character","lua_type":"Model"}],"returns":[],"function_type":"static","source":{"line":198,"path":"src/Server/Util/Character.luau"}},{"name":"onSpawn","desc":"Called when a player\'s character model is placed in the workspace.\\n\\nCurrently only asserts its arguments \u2014 it exists as the post-spawn extension\\npoint, paired with [Character.preSpawn], for logic that needs the character\\nto already be in the world.","params":[{"name":"player","desc":"character owner","lua_type":"Player"},{"name":"character","desc":"the parented character","lua_type":"Model"}],"returns":[],"function_type":"static","source":{"line":242,"path":"src/Server/Util/Character.luau"}}],"properties":[],"types":[],"name":"Character","desc":"The character-spawn seam. Every server-spawned character is built here, so\\nthis is the one place to hook behaviour that must apply to all of them.\\n\\nThe pipeline is three stages:\\n\\n1. [Character.getDescription] resolves the player\'s appearance into a\\n   `HumanoidDescription`, then normalises it \u2014 body scales are pinned and\\n   the back and waist accessory slots are cleared, so avatar choice cannot\\n   change hitbox size or collide with game-owned accessories.\\n2. [Character.createModel] builds an R15 rig from that description and\\n   strips the bundled Roblox scripts, keeping only `Animate` so default\\n   locomotion still works.\\n3. [Character.preSpawn] runs while the model is still parentless \u2014 the point\\n   at which to mutate a character invisibly \u2014 and [Character.onSpawn] fires\\n   once it lands in the Workspace, whether it was parented here or by the\\n   caller.\\n\\nNote this is distinct from `Shared.Class.Character`, which owns held-item\\nwelding and is what [CosmeticService] calls.\\n\\n:::info ItemProcessor is stubbed\\n`Features.Shop.ItemProcessor` was not ported here (TODO Layer 12), so the\\nlocal `ItemProcessor` is nil and the equipped-item loop in\\n[Character.preSpawn] iterates without applying anything.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":34,"path":"src/Server/Util/Character.luau"}}')}}]);